excels.excel:

EXPORT WITH SHEET="银行承兑汇票台账", HEADER=true,
    MAPPING={"a":"汇票号","b":"出票人","c":"承兑银行","d":"票面金额","e":"出票日","f":"到期日","g":"剩余天数","h":"票据状态"},
    FORMAT={"d":"#,##0.00","e":"yyyy-MM-dd","f":"yyyy-MM-dd","g":"0"},
    FORMULAS={
        D7:'SUM(D2:D6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        G4:{color:red,bold:true}
    }
